:root {
  --bg: #02060b;
  --bg2: #06101a;
  --panel: rgba(8, 24, 38, .72);
  --panel-solid: #081826;
  --line: rgba(58, 214, 255, .16);
  --line-strong: rgba(58, 214, 255, .45);
  --text: #d6f4ff;
  --muted: #6f9bb3;
  --accent: #3ad6ff;
  --accent-soft: rgba(58, 214, 255, .12);
  --warm: #ffaa3c;
  --ok: #3ee39a;
  --bad: #ff5a5a;
  --hud-font: "Bahnschrift", "DIN Alternate", "Segoe UI", system-ui, sans-serif;
  --mono: "Cascadia Mono", Consolas, "SF Mono", monospace;
  --cut: 12px;
  font-family: "Segoe UI Variable Text", "Segoe UI", system-ui, sans-serif;
}
* { box-sizing: border-box; }
html, body { height: 100%; margin: 0; }
body { background: var(--bg); color: var(--text); display: grid; grid-template-columns: 330px 1fr; overflow: hidden; }
svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
button { font: inherit; color: inherit; cursor: pointer; border: 0; background: none; }
.hidden { display: none !important; }
.grow { flex: 1; }

/* Hintergrund: Raster, Vignette, Scanlines */
.backdrop { position: fixed; inset: 0; pointer-events: none; z-index: 0;
  background:
    radial-gradient(900px 600px at 18% 40%, rgba(20, 110, 160, .22), transparent 70%),
    radial-gradient(700px 500px at 85% 0%, rgba(20, 80, 140, .14), transparent 70%),
    linear-gradient(rgba(58, 214, 255, .045) 1px, transparent 1px) 0 0 / 34px 34px,
    linear-gradient(90deg, rgba(58, 214, 255, .045) 1px, transparent 1px) 0 0 / 34px 34px; }
.backdrop::after { content: ""; position: absolute; inset: 0;
  background: repeating-linear-gradient(transparent 0 2px, rgba(0, 0, 0, .18) 2px 3px);
  mask-image: radial-gradient(circle at 50% 50%, transparent 40%, black 100%); }

/* ---------- HUD-Seitenleiste ---------- */
.hud { position: relative; z-index: 1; display: flex; flex-direction: column; align-items: center; padding: 26px 22px 18px;
  border-right: 1px solid var(--line); background: linear-gradient(180deg, rgba(4, 16, 26, .85), rgba(2, 8, 14, .9)); overflow-y: auto; }
.corners i { position: absolute; width: 14px; height: 14px; border: 1.5px solid var(--line-strong); }
.corners i:nth-child(1) { top: 8px; left: 8px; border-right: 0; border-bottom: 0; }
.corners i:nth-child(2) { top: 8px; right: 8px; border-left: 0; border-bottom: 0; }
.corners i:nth-child(3) { bottom: 8px; left: 8px; border-right: 0; border-top: 0; }
.corners i:nth-child(4) { bottom: 8px; right: 8px; border-left: 0; border-top: 0; }
.core-wrap { width: 250px; height: 250px; flex: none; position: relative; }
#core { width: 100%; height: 100%; display: block; }
.hud-id { text-align: center; margin: 10px 0 22px; }
.hud-id h1 { margin: 0; font-family: var(--hud-font); font-weight: 600; font-size: 22px; letter-spacing: .5em; padding-left: .5em;
  color: #e9fbff; text-shadow: 0 0 14px rgba(58, 214, 255, .7); }
.status { margin: 8px 0 0; font-family: var(--hud-font); font-size: 12px; letter-spacing: .22em; color: var(--accent); display: inline-flex; align-items: center; gap: 8px; }
.status .dot { width: 7px; height: 7px; border-radius: 50%; background: currentColor; box-shadow: 0 0 8px currentColor; animation: blink 2s infinite; }
.status.thinking { color: #9ff0ff; } .status.listening { color: var(--warm); } .status.error { color: var(--bad); }
@keyframes blink { 50% { opacity: .3; } }

.readouts { width: 100%; margin: 0; display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.readouts div { border: 1px solid var(--line); background: var(--accent-soft); padding: 8px 10px; min-width: 0;
  clip-path: polygon(0 0, calc(100% - 8px) 0, 100% 8px, 100% 100%, 8px 100%, 0 calc(100% - 8px)); }
.readouts div:first-child { grid-column: 1 / -1; }
.readouts dt { font-family: var(--hud-font); font-size: 10px; letter-spacing: .2em; text-transform: uppercase; color: var(--muted); }
.readouts dd { margin: 3px 0 0; font-family: var(--mono); font-size: 13px; color: var(--text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

.update-banner { width: 100%; margin-top: 12px; display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 10px 12px;
  border: 1px solid rgba(62, 227, 154, .5); background: rgba(62, 227, 154, .08); font-size: 13px; }
.hud-actions { display: flex; gap: 8px; margin-top: auto; padding-top: 20px; width: 100%; }
.hud-btn { flex: 1; display: flex; flex-direction: column; align-items: center; gap: 4px; padding: 10px 0 8px; border: 1px solid var(--line); color: var(--muted);
  font-family: var(--hud-font); font-size: 10px; letter-spacing: .18em; text-transform: uppercase; transition: .15s;
  clip-path: polygon(0 0, calc(100% - 8px) 0, 100% 8px, 100% 100%, 8px 100%, 0 calc(100% - 8px)); }
.hud-btn:hover { color: var(--accent); border-color: var(--line-strong); background: var(--accent-soft); }
#speakToggle.off { color: #3c5566; } #speakToggle.off .wave { opacity: 0; }
.version { margin: 12px 0 0; font-family: var(--mono); font-size: 10px; color: #3e6175; letter-spacing: .1em; }

/* ---------- Konsole ---------- */
.console { position: relative; z-index: 1; display: flex; flex-direction: column; min-width: 0; height: 100vh; }
.console-head { display: flex; align-items: center; gap: 12px; padding: 16px 28px 0; }
.tag { font-family: var(--hud-font); font-size: 11px; letter-spacing: .3em; color: var(--accent); }
.tag.dim { color: var(--muted); }
.console-head .line { flex: 1; height: 1px; background: linear-gradient(90deg, var(--line-strong), transparent); }
main { flex: 1; overflow-y: auto; padding: 22px 28px 12px; scroll-behavior: smooth; }

.welcome { height: 100%; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; }
.kicker { font-family: var(--hud-font); letter-spacing: .4em; color: var(--accent); font-size: 12px; margin: 0 0 12px; }
.welcome h2 { margin: 0 0 10px; font-family: var(--hud-font); font-weight: 400; font-size: 34px; letter-spacing: .04em; }
.welcome p { margin: 0 0 22px; color: var(--muted); }
.chips { display: flex; flex-wrap: wrap; gap: 8px; justify-content: center; max-width: 620px; }
.chip { border: 1px solid var(--line); background: var(--panel); padding: 8px 14px; font-size: 13px; color: var(--text); transition: .15s;
  clip-path: polygon(0 0, calc(100% - 7px) 0, 100% 7px, 100% 100%, 7px 100%, 0 calc(100% - 7px)); }
.chip:hover { border-color: var(--line-strong); background: var(--accent-soft); }

#messages { max-width: 860px; margin: 0 auto; display: flex; flex-direction: column; gap: 16px; }
.msg { position: relative; max-width: 86%; padding: 12px 16px; line-height: 1.6; word-wrap: break-word; animation: rise .25s ease-out; }
@keyframes rise { from { opacity: 0; transform: translateY(6px); } }
.msg .who { display: block; font-family: var(--hud-font); font-size: 10px; letter-spacing: .25em; margin-bottom: 4px; }
.msg.user { align-self: flex-end; background: linear-gradient(135deg, rgba(25, 90, 140, .55), rgba(12, 50, 85, .55)); border: 1px solid rgba(58, 214, 255, .35);
  clip-path: polygon(var(--cut) 0, 100% 0, 100% calc(100% - var(--cut)), calc(100% - var(--cut)) 100%, 0 100%, 0 var(--cut)); }
.msg.user .who { color: #8fd8ff; text-align: right; }
.msg.assistant { align-self: flex-start; background: var(--panel); border: 1px solid var(--line); border-left: 2px solid var(--accent); backdrop-filter: blur(6px);
  clip-path: polygon(0 0, calc(100% - var(--cut)) 0, 100% var(--cut), 100% 100%, var(--cut) 100%, 0 calc(100% - var(--cut))); }
